'use strict';
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ReikaTailComposition=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
const COUNT=9;
function defaults(){return Array.from({length:COUNT},(_,i)=>({x:20+i*7.5,y:70+Math.abs(4-i)*2,rotation:(i-4)*-11,scale:1,z:i+1}));}
function validate(items){if(!Array.isArray(items)||items.length!==COUNT)throw new RangeError('Exactly nine tails are required');const zs=new Set();return items.map(item=>{if(!item||!['x','y','rotation','scale','z'].every(k=>Number.isFinite(item[k])))throw new TypeError('Invalid tail transform');if(item.x<0||item.x>100||item.y<0||item.y>100||Math.abs(item.rotation)>180||item.scale<.2||item.scale>3||!Number.isInteger(item.z)||item.z<1||item.z>COUNT||zs.has(item.z))throw new RangeError('Tail transform out of range or duplicate z');zs.add(item.z);return {...item};});}
function mount(){const after=document.querySelector('.layer-player');if(!after)return;
const section=document.createElement('section');section.className='tail-composition';section.innerHTML='<h2>Композиция девяти хвостов · эксперимент</h2><p>Загрузите девять прозрачных экспериментальных PNG из v33. Положение относительно силуэта условное, не анатомическая привязка.</p><label for="tailCompositionFiles">Девять PNG хвостов</label><input id="tailCompositionFiles" type="file" accept="image/png" multiple><label for="tailCompositionSelect">Хвост</label><select id="tailCompositionSelect"></select><label for="tailCompX">Положение X (%)</label><input id="tailCompX" type="range" min="0" max="100" step="1"><label for="tailCompY">Положение Y (%)</label><input id="tailCompY" type="range" min="0" max="100" step="1"><label for="tailCompRotation">Поворот (°)</label><input id="tailCompRotation" type="range" min="-180" max="180" step="1"><label for="tailCompScale">Масштаб (%)</label><input id="tailCompScale" type="range" min="20" max="300" step="5"><button id="tailCompFront" type="button">Вперёд по слоям</button><button id="tailCompReset" type="button">Сбросить</button><button id="tailCompExport" type="button">Скопировать параметры</button><p id="tailCompositionStatus" role="status" aria-live="polite">Нет загруженных изображений.</p><div id="tailCompositionStage" style="position:relative;max-width:640px;aspect-ratio:4/5;overflow:hidden;background:linear-gradient(#202237,#44405a);border:1px solid #777;border-radius:12px"></div>';after.after(section);
const stage=section.querySelector('#tailCompositionStage'),input=section.querySelector('#tailCompositionFiles'),select=section.querySelector('#tailCompositionSelect'),status=section.querySelector('#tailCompositionStatus');const ranges={x:section.querySelector('#tailCompX'),y:section.querySelector('#tailCompY'),rotation:section.querySelector('#tailCompRotation'),scale:section.querySelector('#tailCompScale')};let state=defaults(),urls=[];const images=[];
for(let i=0;i<COUNT;i++){const option=document.createElement('option');option.value=String(i);option.textContent='Хвост '+(i+1);select.append(option);const img=document.createElement('img');img.alt='Хвост '+(i+1);img.style.cssText='position:absolute;width:25%;height:auto;max-height:40%;object-fit:contain;pointer-events:none';img.hidden=true;images.push(img);stage.append(img);}
function paint(){state=validate(state);for(let i=0;i<COUNT;i++){const item=state[i],image=images[i];image.style.left=item.x+'%';image.style.top=item.y+'%';image.style.zIndex=String(item.z);image.style.transform='translate(-50%,-90%) rotate('+item.rotation+'deg) scale('+item.scale+')';}}
function sync(){const selected=state[Number(select.value)||0];ranges.x.value=selected.x;ranges.y.value=selected.y;ranges.rotation.value=selected.rotation;ranges.scale.value=selected.scale*100;}
select.addEventListener('change',sync);
for(const [key,control] of Object.entries(ranges))control.addEventListener('input',()=>{const index=Number(select.value)||0;state[index]={...state[index],[key]:key==='scale'?Number(control.value)/100:Number(control.value)};paint();});
section.querySelector('#tailCompFront').onclick=()=>{const i=Number(select.value)||0;const current=state[i].z;if(current===COUNT)return;const other=state.findIndex((t,j)=>j!==i&&t.z===current+1);state[i].z=current+1;state[other].z=current;paint();};
section.querySelector('#tailCompReset').onclick=()=>{state=defaults();paint();sync();status.textContent='Параметры сброшены.';};
section.querySelector('#tailCompExport').onclick=()=>{const serialized=JSON.stringify({version:35,status:'EXPERIMENTAL_REFERENCE_PLACEMENT',tails:validate(state)},null,2);if(navigator.clipboard?.writeText){navigator.clipboard.writeText(serialized).then(()=>{status.textContent='Параметры скопированы.';},()=>{status.textContent='Не удалось скопировать; используйте защищённый контекст.';});}else status.textContent='Буфер обмена недоступен.';};
input.addEventListener('change',()=>{urls.forEach(url=>URL.revokeObjectURL(url));urls=[];for(const image of images){image.hidden=true;image.removeAttribute('src');}const files=Array.from(input.files||[]);if(files.length!==COUNT||files.some(file=>file.type!=='image/png'||file.size>20*1024*1024)){status.textContent='Выберите ровно 9 PNG (до 20 МБ каждый).';return;}files.forEach((file,i)=>{const url=URL.createObjectURL(file);urls.push(url);images[i].src=url;images[i].hidden=false;});status.textContent='Загружено 9 PNG для тестовой композиции.';});
window.addEventListener('pagehide',()=>urls.forEach(url=>URL.revokeObjectURL(url)),{once:true});paint();sync();return {get state(){return validate(state);},setState(next){state=validate(next);paint();sync();}};}
return {COUNT,defaults,validate,mount};
});
if(typeof window!=='undefined')window.ReikaTailCompositionController=window.ReikaTailComposition.mount();
